os.chdir(ROOT)
run = sys.argv[1]
out = ROOT / 'out' / run
out.mkdir()
remote_out = WORKER + '/out/' + run
status = {'run': run, 'engine_sha': E_SHA, 'attempts': [], 'serving': False}
holds, captures = [], []
ranks, guard, arm, token, label = [], None, 'D', None, None
LOOSE = False


def receipt(path, value):
    path.write_text(json.dumps(value, indent=2) + '\n')


def save():
    receipt(out / 'status.json', status)


def remote(args, user='root'):
    return SSH + [user + '@<rank1-link-ip>', shlex.join(list(map(str, args)))]


def command(args, timeout=180, **kw):
    return subprocess.run(list(map(str, args)), check=True, timeout=timeout, **kw)


def api(path, body=None, timeout=900):
    req = urllib.request.Request('http://127.0.0.1:8000' + path, None if body is None else json.dumps(body).encode(),
                                 {'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.load(r)


def action(rank, verb):
    path = str(out / 'foreign-r0.json') if rank == 0 else remote_out + '/foreign-r1.json'
    args = ['python3', str(ROOT / 'ops/foreign-jobs.py') if rank == 0 else WORKER + '/ops/foreign-jobs.py', verb, path, '--rank', str(rank)]
    with (out / f'foreign-{verb}-r{rank}.log').open('a') as log:
        command(args if rank == 0 else remote(args), stdout=log, stderr=subprocess.STDOUT)


def manifest(name, pack, extra):
    """arms-<name>.json: arms-ehx.json (K6) or arms-ek4.json (K4 pack, H's prepared identity) with E's rank configs =
    that label's D env + the overrides (later lines win when the env is sourced)."""
    base = os.environ.get('EF_BASE', 'ehx') if pack == 'k6' else 'ek4'  # candidate G: EF_BASE=fg (make-g.py)
    m = json.loads((ROOT / f'arms-{base}.json').read_text())
    assert m['arms']['D']['engine_sha'] == E_SHA
    for rank in (0, 1):
        text = (ROOT / 'config' / f'{base}-D-r{rank}.env').read_text().rstrip('\n') + '\n' + ''.join(x + '\n' for x in extra)
        assert not any(b in text for b in ('KV_SPLIT_DEDUP', 'KV_SPLIT_EARLY', 'TF_TP_ROCE_CHUNKED_KB'))
        local = ROOT / 'config' / f'{name}-D-r{rank}.env'
        local.write_text(text)
        if rank:
            command(['scp', '-q', local, f'<rank1-user>@<rank1-link-ip>:{WORKER}/config/{local.name}'])
            m['arms']['D']['ranks'][1]['config'] = f'{WORKER}/config/{local.name}'
        else:
            m['arms']['D']['ranks'][0]['config'] = str(local)
    if pack == 'k6':
        m['arms']['D']['assets_receipt'] = 'evidence/ASSETS-VERIFIED-K6.json'  # K6 dense-MTP pack (ops/rank.py)
    m['arms']['D']['description'] = f'candidate E {name} ({pack}): ' + ' '.join(extra or ['all on'])
    path = ROOT / f'arms-{name}.json'
    path.write_text(json.dumps(m, indent=2) + '\n')
    command(['scp', '-q', path, f'<rank1-user>@<rank1-link-ip>:{WORKER}/{path.name}'])
    return name


def start(job):
    global ranks, guard, token
    token = f'{run}-{job}'
    env = dict(os.environ, DSV41_MANIFEST=str(ROOT / f'arms-{label}.json'))
    with (out / job / 'cool.log').open('w') as log:
        command(['bash', 'ops/cool.sh'], timeout=1800, env=dict(env, COOL_TIMEOUT_S='1740'), stdout=log, stderr=subprocess.STDOUT)
    guard = subprocess.Popen(['python3', 'ops/guard.py', str(out / job), str(os.getpid())],
                             stdout=(out / job / 'guard.log').open('w'), stderr=subprocess.STDOUT)
    ranks = []
    for rank in (1, 0):
        args = ['python3', str(ROOT / 'ops/rank.py'), 'start', arm, str(rank), token]
        if rank:
            args = remote(['env', 'DSV41_BENCH_ROOT=' + WORKER, 'DSV41_MANIFEST=' + WORKER + f'/arms-{label}.json',
                           'python3', WORKER + '/ops/rank.py', 'start', arm, '1', token])
        ranks.append(subprocess.Popen(args, stdout=(out / job / f'rank{rank}.log').open('w'), stderr=subprocess.STDOUT, env=env))
    deadline = time.monotonic() + 3600
    while time.monotonic() < deadline:
        assert all(p.poll() is None for p in ranks), 'native rank exited before readiness'
        assert guard.poll() is None, 'thermal guard exited'
        try:
            with urllib.request.urlopen('http://127.0.0.1:8000/v1/models', timeout=3) as r:
                return json.load(r)
        except (OSError, ValueError):
            time.sleep(2)
    raise RuntimeError('HTTP readiness timed out')


def stop(job):
    global ranks, guard
    errors = []
    if guard:
        guard.terminate()
        guard.wait(timeout=30)
        guard = None
    for rank in (0, 1):
        args = ['python3', str(ROOT / 'ops/rank.py'), 'cancel', arm, str(rank), token]
        if rank:
            args = remote(['env', 'DSV41_BENCH_ROOT=' + WORKER, 'DSV41_MANIFEST=' + WORKER + f'/arms-{label}.json',
                           'python3', WORKER + '/ops/rank.py', 'cancel', arm, '1', token])
        try:
            with (out / job / f'stop-r{rank}.log').open('w') as log:
                command(args, timeout=150, stdout=log, stderr=subprocess.STDOUT,
                        env=dict(os.environ, DSV41_MANIFEST=str(ROOT / f'arms-{label}.json')))
        except BaseException as exc:
            errors.append(repr(exc))
    for child in ranks:
        try:
            child.wait(timeout=60)
        except subprocess.TimeoutExpired:
            errors.append('rank launcher did not settle')
    for rank in (0, 1):
        try:
            args = ['bash', str(ROOT / 'ops/node.sh'), 'idle']
            command(args if rank == 0 else remote(['bash', 'work/dsv41-bench/ops/node.sh', 'idle'], 'rank1-host'))
        except BaseException as exc:
            errors.append('GPU not drained: ' + repr(exc))
    ranks = []
    return errors


def gates(job, model):
    spec = __import__('importlib.util').util.spec_from_file_location('bench_workload', ROOT / 'workload/driver.py')
    w = __import__('importlib.util').util.module_from_spec(spec)
    spec.loader.exec_module(w)
    (out / job / 'gates').mkdir()
    w.OUT, w.BASE, w.MODEL, w.TIMEOUT, w.TOKENS = out / job / 'gates', 'http://127.0.0.1:8000', model, 600, 2048
    res = {}
    w.smoke()
    res['smoke'] = True
    tools = [{'type': 'function', 'function': {'name': 'lookup', 'strict': True, 'description': 'Look up a term.',
              'parameters': {'type': 'object', 'properties': {'q': {'type': 'string'}, 'n': {'type': 'integer'}},
                             'required': ['q', 'n'], 'additionalProperties': False}}},
             {'type': 'function', 'function': {'name': 'now', 'description': 'The current time in a timezone.',
              'parameters': {'type': 'object', 'properties': {'tz': {'type': 'string'}}}}}]
    cases = []
    for choice, prompt, want in (('required', 'Look up the 3 best results for "tensor parallelism".', 'lookup'),
                                 ('auto', 'What time is it in UTC right now? Use the now tool.', 'now')):
        reply = api('/v1/chat/completions', dict(w.body(prompt, tokens=1024, draft=False), tools=tools, tool_choice=choice))
        cases.append({'choice': choice, 'response': reply})
        receipt(out / job / 'gates' / 'strict-tools.json', cases)
        calls = reply['choices'][0]['message'].get('tool_calls') or []
        assert calls and calls[0]['function']['name'] == want, ('strict tools', choice, calls)
        if want == 'lookup':
            a = json.loads(calls[0]['function']['arguments'])
            assert set(a) == {'q', 'n'} and isinstance(a['q'], str) and type(a['n']) is int, a
    res['strict_tools'] = True
    request = w.body('Write a detailed, coherent tutorial of at least 2500 words explaining how a relational database executes a SQL query. Cover parsing, planning, indexes, joins, transactions and recovery. Start directly with the tutorial and continue until the answer is complete.', tokens=2048, draft=False)
    reply = api('/v1/chat/completions', request)
    ids = reply.get('tensorfold', {}).get('token_ids')
    receipt(out / job / 'gates' / 'greedy-2k-token-ids.json', ids)
    res['greedy_2k_sha256'] = hashlib.sha256(json.dumps(ids).encode()).hexdigest()
    res['greedy_2k_equal_H'] = res['greedy_2k_sha256'] == H2K
    assert LOOSE or res['greedy_2k_equal_H'], ('greedy 2K differs from H', res['greedy_2k_sha256'])
    ref = json.loads(H8K.read_text())
    req8 = dict(ref['request'], model=model)
    assert len(req8['prompt']) == 8192
    r8 = api('/v1/completions', req8)
    receipt(out / job / 'gates' / 'prefill-8192.json', {'request_from': str(H8K), 'response': r8})
    got, want8 = r8.get('tensorfold', {}).get('token_ids'), ref['response']['tensorfold']['token_ids']
    res['exact_8192_equal_H'] = bool(got) and got == want8
    assert LOOSE or res['exact_8192_equal_H'], 'the 8K cell token IDs differ from H'
    return res




def interrupted(signum, frame):
    raise RuntimeError('interrupted: ' + str(signum))


def run_config(cfg):
    global label, LOOSE
    name = cfg['name']
    LOOSE = bool(cfg.get('loose'))
    label = manifest(name, cfg['pack'], cfg['extra'])
    (out / name).mkdir()
    attempt = dict(cfg, job=name, started=time.strftime('%FT%TZ', time.gmtime()))
    status['attempts'].append(attempt)
    save()
    t0 = time.monotonic()
    try:
        models = start(name)
        attempt['ready_s'] = time.monotonic() - t0
        print('READY', name, round(attempt['ready_s']), flush=True)
        attempt.update(gates(name, models['data'][0]['id']))
        attempt['pass'] = True
    except BaseException as exc:
        attempt['error'] = repr(exc)[:2000]
        attempt['pass'] = False
        print('FAIL', name, repr(exc)[:500], flush=True)
        if isinstance(exc, RuntimeError) and str(exc).startswith('interrupted'):
            raise
    logs = [(out / name / f'rank{r}.log').read_text(errors='replace') if (out / name / f'rank{r}.log').exists() else '' for r in (0, 1)]
    attempt['missing_triton_variant'] = sum(t.count('MissingTritonVariant') for t in logs)
    save()
    if not attempt['pass']:
        return False
    meta = json.loads((ROOT / f'arms-{label}.json').read_text())['arms']['D']
    receipt(out / name / 'arm-metadata.json', dict(tp=2, arm='D', **meta))
    if cfg.get('decode'):
        with (out / name / ('decode-' + cfg['decode'] + '.txt')).open('w') as log:
            attempt['decode_rc'] = subprocess.run(['python3', '-I', '<rank0-work>/imr-te/runner_decode_check.py', cfg['decode']],
                                                  stdout=log, stderr=subprocess.STDOUT, timeout=1200).returncode
        save()
    if cfg.get('measure'):
        with (out / name / 'window-boot.log').open('w') as log:
            attempt['measure_rc'] = subprocess.run(['python3', '-B', '<rank0-work>/ab3-20261104/t05/window_boot.py',
                                                    str(out / name), json.dumps(cfg)], stdout=log,
                                                   stderr=subprocess.STDOUT, timeout=21600).returncode
    if cfg.get('deadline_check'):
        # T2 dadaa0e24 on the served image: deadline_s ends a reply with finish deadline, usage, ids and receipt
        save()
        with (out / name / 'deadline.log').open('w') as log:
            attempt['deadline_rc'] = subprocess.run(['python3', '-I', '<rank0-work>/imr-te/imr-deadline-check.py', str(out / name),
                                                     models['data'][0]['id']], stdout=log, stderr=subprocess.STDOUT, timeout=1200).returncode
    save()
    return True


signal.signal(signal.SIGTERM, interrupted)
signal.signal(signal.SIGINT, interrupted)
try:
    command(remote(['mkdir', '-p', remote_out]))
    for rank in (0, 1):
        action(rank, 'capture')
        captures.append(rank)
    for rank in (0, 1):
        command(['bash', 'ops/node.sh', 'hold', run] if rank == 0 else remote(['bash', 'work/dsv41-bench/ops/node.sh', 'hold', run], 'rank1-host'))
        holds.append(rank)
    for rank in captures:
        action(rank, 'stop')
    for rank in (0, 1):
        command(['bash', 'ops/node.sh', 'idle'] if rank == 0 else remote(['bash', 'work/dsv41-bench/ops/node.sh', 'idle'], 'rank1-host'))
    configs = json.loads(Path(sys.argv[2]).read_text())
    t_loop, ran = time.monotonic(), set()
    for i, cfg in enumerate(configs):
        late = cfg.get('start_by_s') and time.monotonic() - t_loop > cfg['start_by_s']
        abort = (out / 'ABORT').exists()  # a boot's preflight failed: nothing more in this turn
        if late or abort or not set(cfg.get('needs', [])) <= ran:
            print('CONFIG-SKIPPED', cfg['name'], 'abort' if abort else 'late' if late else 'needs', flush=True)
            status.setdefault('skipped', []).append(cfg['name'])
            continue
        ran.add(cfg['name'])
        if ran != {cfg['name']} and ranks:
            errors = stop(status['attempts'][-1]['job'])
            if errors:
                raise RuntimeError('ranks did not stop cleanly: ' + str(errors))
        status['current'] = cfg['name']
        ok = run_config(cfg)
        save()
        print('CONFIG-DONE', cfg['name'], ok, flush=True)
        if not ok:
            break
    raise SystemExit(0)
except SystemExit:
    print('STOP requested', flush=True)
except BaseException as exc:
    status['error'] = repr(exc)[:2000]
    print('EFAST_FAILED', repr(exc)[:500], flush=True)
finally:
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    errors = stop(status['attempts'][-1]['job']) if ranks else []
    for rank in (holds if not errors else []):
        try:
            command(['bash', 'ops/node.sh', 'release', run] if rank == 0 else remote(['bash', 'work/dsv41-bench/ops/node.sh', 'release', run], 'rank1-host'))
        except BaseException as exc:
            errors.append(repr(exc))
    for rank in (captures if not errors else []):
        try:
            action(rank, 'restore')
        except BaseException as exc:
            errors.append(repr(exc))
    status['serving'] = False
    status['cleanup_errors'] = errors
    save()
    print('EFAST_END', json.dumps({'current': status.get('current'), 'cleanup_errors': errors}), flush=True)
